INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_VODOU','Haitian Vodou (colonial Saint-Domingue formation to present)',1700,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_MURPHY_WORKING_SPIRIT','secondary scholarship','Joseph M. Murphy, Working the Spirit: Ceremonies of the African Diaspora (Beacon Press, 1994)','Afro-diasporic religions incl. Haitian Vodou; ceremony, lwa, saint syncretism'),
 ('SRC_METRAUX_VOODOO_HAITI','secondary scholarship','Alfred Métraux, Voodoo in Haiti (trans. Hugo Charteris, Oxford UP, 1959)','Ethnography of Haitian Vodou; the lwa, nanchon, possession, and Catholic syncretism')
INSERT INTO _e VALUES
 ('ENT_VOD_BONDYE','Bondye','deity','creator deity','Vodou','supreme creator; transcendence','B','The remote, supreme creator God of Haitian Vodou (from French ''Bon Dieu''); identified with the Christian God, served indirectly through the lwa. Living tradition; modern.'),
 ('ENT_VOD_LWA','The Lwa','collective','pantheon/collective','Vodou','served spirits; intermediaries','B','Collective hub for the lwa (mistè), the served spirits who mediate between Bondye and humanity, organized in nanchon (chiefly Rada and Petwo). Living tradition.'),
 ('ENT_VOD_RADA','Rada nanchon','collective','pantheon/collective','Vodou','cool, beneficent spirits; ancestral Dahomean rite','B','The Rada nanchon: ''cool'' (dou) lwa of largely Fon/Dahomean derivation, served in the Rada rite. Publicly documented organizing category. Living tradition.'),
 ('ENT_VOD_PETWO','Petwo nanchon','collective','pantheon/collective','Vodou','hot, forceful spirits; New-World/Kongo rite','B','The Petwo (Petro) nanchon: ''hot'' (cho) lwa of New-World and Kongo derivation, served in the Petwo rite. Publicly documented organizing category. Living tradition.'),
 ('ENT_VOD_LEGBA','Papa Legba','deity','lwa','Vodou','crossroads; gates; opener of the way','B','Rada lwa, the gatekeeper opening the way between worlds; saluted first in ceremony. Publicly identified in Vodou imagery with St Peter (keys) and St Lazarus. Living tradition.'),
 ('ENT_VOD_ERZULIE_FREDA','Erzulie Freda','deity','lwa','Vodou','love; beauty; luxury; feminine grace','B','Rada lwa of love and beauty; her chromolithograph is widely the Mater Dolorosa. Publicly attested. Living tradition.'),
 ('ENT_VOD_ERZULIE_DANTOR','Erzulie Dantor','deity','lwa','Vodou','fierce mother-protector; single mothers; defense','B','Petwo lwa, fierce protective mother; popularly imaged as the Black Madonna of Częstochowa (and St Barbara). Publicly attested. Living tradition.'),
 ('ENT_VOD_DAMBALLA','Damballa Wedo','deity','lwa','Vodou','serpent; creation; sky; purity; ancestral wisdom','B','Rada serpent lwa, ancient and benevolent creator-associated spirit, consort of Ayida-Wedo; popularly imaged as St Patrick (serpents). Publicly attested. Living tradition.'),
 ('ENT_VOD_AYIDA_WEDO','Ayida-Wedo','deity','lwa','Vodou','rainbow serpent; sky; fertility','B','Rada rainbow-serpent lwa, consort of Damballa; the serpent pair embodies cosmic balance. Publicly attested. Living tradition.'),
 ('ENT_VOD_BARON_SAMEDI','Baron Samedi','deity','lwa','Vodou','death; cemeteries; the dead; healing of the dying','B','Chief of the Gede; lord of cemeteries and the dead, associated with the cemetery cross. Publicly attested. Living tradition; not modeled here as a ''narco-saint'' or sensationalized figure.'),
 ('ENT_VOD_GEDE','The Gede','collective','lwa family/collective','Vodou','the dead; ancestors; fertility; ribald humor','B','Family (and Petwo-adjacent nanchon) of lwa of death and the ancestors, led by the Barons and Maman Brigitte. Publicly attested. Living tradition.'),
 ('ENT_VOD_MAMAN_BRIGITTE','Maman Brigitte','deity','lwa','Vodou','death; cemeteries; consort of Baron; protector of graves','B','Gede lwa, consort of Baron Samedi, mistress of the cemetery; her name reflects the Irish Brigid heritage of the diaspora. Publicly attested. Living tradition.'),
 ('ENT_VOD_OGOU','Ogou','deity','lwa','Vodou','iron; war; fire; soldiers; political power','B','Lwa of iron and war (Yoruba-derived Ogun), served across nanchon; popularly imaged as St James the Greater (Santiago Matamoros). Publicly attested. Living tradition.'),
 ('ENT_VOD_AGWE','Agwe','deity','lwa','Vodou','the sea; ships; sovereign of the waters','B','Rada lwa, sovereign of the sea and patron of sailors and fishermen, consort of La Sirène. Publicly attested. Living tradition.'),
 ('ENT_VOD_LASIRENE','La Sirène','deity','lwa','Vodou','the sea; wealth; music; mermaid spirit','B','Lwa of the sea, a mermaid spirit linked to Agwe and to the water-mother complex (Lasirèn/Labalèn). Publicly attested. Living tradition.'),
 ('ENT_VOD_MARASSA','The Marassa','deity','lwa','Vodou','divine twins; children; doubling; reciprocity','B','The sacred Marassa (divine twins), among the first lwa served; popularly imaged as Sts Cosmas and Damian. Publicly attested. Living tradition.'),
 ('ENT_VOD_LOKO','Loko','deity','lwa','Vodou','sacred trees; healing; patron of priests (oungan)','B','Rada lwa of vegetation and healing, patron of the priesthood and of the poto-mitan/sacred tree, consort of Ayizan. Publicly attested. Living tradition.'),
 ('ENT_VOD_SIMBI','Simbi','deity','lwa','Vodou','fresh water; springs; magic; messenger','B','Lwa (Kongo-derived, often Petwo) of fresh water, springs and rain, associated with magic and patronage of healers/sorcerers. Publicly attested. Living tradition.');
