INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_VOD_LWA','emanates_from','ENT_VOD_BONDYE','high','The lwa serve and mediate the remote creator Bondye, who is their ultimate source (Métraux; Murphy).'),
 ('ENT_VOD_RADA','member_of','ENT_VOD_LWA','high','Rada is one of the principal nanchon (divisions) of the lwa.'),
 ('ENT_VOD_PETWO','member_of','ENT_VOD_LWA','high','Petwo is one of the principal nanchon (divisions) of the lwa.'),
 ('ENT_VOD_LEGBA','member_of','ENT_VOD_LWA','high','Papa Legba is a lwa.'),
 ('ENT_VOD_LEGBA','member_of','ENT_VOD_RADA','high','Legba is served as a Rada lwa, saluted first in ceremony (Métraux).'),
 ('ENT_VOD_ERZULIE_FREDA','member_of','ENT_VOD_RADA','high','Erzulie Freda Dahomey is a Rada lwa of love and beauty (Murphy).'),
 ('ENT_VOD_ERZULIE_DANTOR','member_of','ENT_VOD_PETWO','high','Erzulie Dantor is the fierce Petwo counterpart of Erzulie (Murphy).'),
 ('ENT_VOD_ERZULIE_DANTOR','opposes','ENT_VOD_ERZULIE_FREDA','medium','The Petwo Dantor and Rada Freda form the documented hot/cool polarity of the Erzulie complex (Murphy).'),
 ('ENT_VOD_DAMBALLA','member_of','ENT_VOD_RADA','high','Damballa Wedo is the senior Rada serpent lwa (Métraux).'),
 ('ENT_VOD_AYIDA_WEDO','member_of','ENT_VOD_RADA','high','Ayida-Wedo is a Rada serpent lwa (Métraux).'),
 ('ENT_VOD_AYIDA_WEDO','consort_of','ENT_VOD_DAMBALLA','high','Ayida-Wedo and Damballa are the paired rainbow/serpent consorts (Métraux).'),
 ('ENT_VOD_BARON_SAMEDI','member_of','ENT_VOD_GEDE','high','Baron Samedi heads the Gede family of death lwa (Murphy).'),
 ('ENT_VOD_GEDE','member_of','ENT_VOD_LWA','high','The Gede are a family/nanchon within the lwa.'),
 ('ENT_VOD_MAMAN_BRIGITTE','member_of','ENT_VOD_GEDE','high','Maman Brigitte is a Gede lwa of the cemetery (Murphy).'),
 ('ENT_VOD_MAMAN_BRIGITTE','consort_of','ENT_VOD_BARON_SAMEDI','high','Maman Brigitte is the documented consort of Baron Samedi (Murphy).'),
 ('ENT_VOD_OGOU','member_of','ENT_VOD_LWA','high','Ogou (Yoruba-derived Ogun) is a lwa of iron and war served across nanchon (Murphy).'),
 ('ENT_VOD_AGWE','member_of','ENT_VOD_RADA','high','Agwe, sovereign of the sea, is a Rada lwa (Métraux).'),
 ('ENT_VOD_LASIRENE','member_of','ENT_VOD_LWA','high','La Sirène, the mermaid sea spirit, is a lwa (Métraux).'),
 ('ENT_VOD_LASIRENE','consort_of','ENT_VOD_AGWE','medium','La Sirène is paired with Agwe in the marine complex of lwa (Métraux).'),
 ('ENT_VOD_MARASSA','member_of','ENT_VOD_LWA','high','The Marassa (divine twins) are among the lwa served (Murphy).'),
 ('ENT_VOD_LOKO','member_of','ENT_VOD_RADA','high','Loko is a Rada lwa, patron of the priesthood (Métraux).'),
 ('ENT_VOD_SIMBI','member_of','ENT_VOD_LWA','high','Simbi, the Kongo-derived water lwa, is a lwa often served in Petwo (Métraux).'),
 ('ENT_VOD_SIMBI','member_of','ENT_VOD_PETWO','medium','Simbi is frequently served within the Petwo nanchon (Métraux).'),
 ('ENT_VOD_LEGBA','syncretized_with','ENT_SAINT_PETER','high','Papa Legba, keeper of the gates, is popularly identified with St Peter (the keys) in Vodou chromolithography (Métraux; Murphy).'),
 ('ENT_VOD_LEGBA','syncretized_with','ENT_NT_LAZARUS_BETHANY','medium','In some lineages the aged, crutch-bearing Legba is imaged as St Lazarus (Métraux).'),
 ('ENT_VOD_LEGBA','aligned_with','ENT_SAINT_ANTHONY_PADUA','medium','St Anthony of Padua is also documented as a chromolithographic image for Legba in parts of Haiti (Métraux).'),
 ('ENT_VOD_ERZULIE_FREDA','syncretized_with','ENT_MARY_SORROWS','high','Erzulie Freda is popularly identified with the Mater Dolorosa / Our Lady of Sorrows (Murphy; Métraux).'),
 ('ENT_VOD_ERZULIE_DANTOR','syncretized_with','ENT_MARY_CZESTOCHOWA','high','Erzulie Dantor is popularly imaged as the Black Madonna of Częstochowa (Murphy).'),
 ('ENT_VOD_ERZULIE_DANTOR','aligned_with','ENT_CHR_BARBARA','medium','St Barbara also appears among the Catholic images associated with the fierce Erzulie Dantor in Vodou practice (Murphy).'),
 ('ENT_VOD_OGOU','syncretized_with','ENT_SAINT_JAMES_GREATER','high','Ogou is popularly identified with St James the Greater (Santiago, the mounted warrior) (Murphy; Métraux).'),
 ('ENT_VOD_MARASSA','syncretized_with','ENT_SAINT_COSMAS_DAMIAN','high','The divine twins Marassa are popularly imaged as Sts Cosmas and Damian, the holy twin physicians (Murphy; Métraux).');
